// ══════════════════════════════════════════════════
// TROUVER L'ATTACHEMENT — Parcourir payload.parts
// Gmail structure multipart: parts imbriquées
// On cherche la première part avec filename + body.attachmentId
// ══════════════════════════════════════════════════
const msg = $input.first().json;

function findAttachments(parts, results = []) {
  if (!parts) return results;
  for (const part of parts) {
    const hasAttachId = part.body?.attachmentId;
    const hasFilename = part.filename && part.filename.length > 0;
    if (hasAttachId && hasFilename) {
      results.push({
        partId:       part.partId,
        attachmentId: part.body.attachmentId,
        filename:     part.filename,
        mimeType:     part.mimeType,
        size:         part.body.size || 0
      });
    }
    // Récursif pour multipart/mixed, multipart/related, etc.
    if (part.parts) findAttachments(part.parts, results);
  }
  return results;
}

const attachments = findAttachments(msg.payload?.parts || []);

if (attachments.length === 0) {
  // Cas edge: pièce jointe inline ou email sans attachment structuré
  throw new Error(
    `Aucune pièce jointe trouvée dans la structure Gmail.\n` +
    `mimeType: ${msg.payload?.mimeType}\n` +
    `Parts disponibles: ${JSON.stringify((msg.payload?.parts||[]).map(p => ({mimeType: p.mimeType, filename: p.filename, hasAttach: !!p.body?.attachmentId})))}`
  );
}

// Priorité: PDF > image > autre
const pdf = attachments.find(a => a.mimeType?.includes('pdf'));
const img = attachments.find(a => a.mimeType?.startsWith('image/'));
const chosen = pdf || img || attachments[0];

const meta = $('⚙️ Normaliser Source').first().json;

return [{
  json: {
    ...meta,
    _gmailId:     msg.id,
    _attachId:    chosen.attachmentId,
    _partId:      chosen.partId,
    fileName:     chosen.filename,
    mimeType:     chosen.mimeType,
    _attachSize:  chosen.size,
    _allAttachments: attachments.length
  }
}];

// ══════════════════════════════════════════════════
// DÉCODER PJ BASE64 → BINAIRE
// L'API Gmail retourne: { size, data: "<base64url>" }
// n8n attend un binaire dans item.binary.data
// ══════════════════════════════════════════════════
const apiResp = $input.first().json;
const meta    = $('🗂️ Gmail — Trouver PJ').first().json;

// Gmail utilise base64url (- et _ au lieu de + et /)
const base64url = apiResp.data;
if (!base64url) {
  throw new Error('Réponse API Gmail vide — champ data absent: ' + JSON.stringify(Object.keys(apiResp)));
}

// Convertir base64url → base64 standard
const base64std = base64url.replace(/-/g, '+').replace(/_/g, '/');

return [{
  json: {
    ...meta,
    fileName: meta.fileName,
    mimeType: meta.mimeType
  },
  binary: {
    data: {
      data:     base64std,
      mimeType: meta.mimeType || 'application/pdf',
      fileName: meta.fileName || 'facture.pdf',
      fileSize: apiResp.size || 0,
      fileExtension: (meta.fileName || 'pdf').split('.').pop()
    }
  }
}];

// ══════════════════════════════════════════════════
// WATCHDOG L1 — Analyser résultat Staging (fileId)
// _STAGING: A=fileId, B=processedAt, C=statut
// ══════════════════════════════════════════════════
const meta = $('⚙️ Normaliser Source').first().json;
const fileId = meta.fileId || '';

let l1Hit = null;
try {
  const resp = $('🐕 WD L1 — fileId dans Staging').first().json;
  const cols = resp.values || [];
  const colA = cols[0] || [];
  const colB = cols[1] || [];
  const colC = cols[2] || [];
  const idx = colA.findIndex((v, i) => i > 0 && v === fileId);
  if (idx >= 0) {
    l1Hit = {
      fileId,
      processedAt: colB[idx] || 'inconnu',
      statut:      colC[idx] || 'INCONNU'
    };
  }
} catch(e) {}

const isDoublon = !!l1Hit;

return [{
  json: {
    ...meta,
    _isDoublon:     isDoublon,
    _doublonSource: l1Hit ? 'STAGING' : null,
    _doublonStatut: l1Hit?.statut      || null,
    _doublonDate:   l1Hit?.processedAt || null,
    _doublonDetail: l1Hit              || null
  }
}];

